mapper.select:
select  from mall_order

    and user_id = #{userId}
    and status = #{status}
    and order_number = #{orderNumber}

order by create_time desc, id desc

mapper.update:
update mall_order
status = #{to}, pay_status = #{update.payStatus}, pay_method = #{update.payMethod}, cancel_reason = #{update.cancelReason}, cancel_time = #{update.cancelTime}, pay_time = #{update.payTime}, delivery_time = #{update.deliveryTime}, receive_time = #{update.receiveTime}, update_time = now()
where id = #{id} and status = #{from}
